fn knapsack(weights, values, capacity):
    var dp = table(5, capacity + 1, 0)
    for i in 1..=4:
        for c in 1..=capacity:
            dp[i][c] = dp[i - 1][c]
            if c >= weights[i - 1]:
                let rest = c - weights[i - 1]
                dp[i][c] = max(dp[i][c],
                    dp[i][rest] + values[i - 1])
    dp[4][capacity]

// spec uses dp[i - 1][rest] on line 9
// Each item may be chosen at most once.
